import type { GameRoom } from "./GameRoom";
import type { RateLimiter } from "./durable/RateLimiter";
import type { Updater } from "./durable/Updater";

export interface Env {
  DB: D1Database;
  GAME_ROOM: DurableObjectNamespace<GameRoom>;
  RATE_LIMITER: DurableObjectNamespace<RateLimiter>;
  UPDATER: DurableObjectNamespace<Updater>;
  ASSETS: Fetcher;
  /** Random secret generated by the installer; keys IP hashing. Required for login. */
  SESSION_SECRET: string;
  /** Random secret generated by the installer; signs the short-lived host and projector WebSocket tickets. */
  WS_TICKET_SECRET: string;
  /** One-time token that authorises creating the first administrator. Present only during setup. */
  SETUP_TOKEN?: string;
  /** PBKDF2 iterations calibrated for this account's CPU budget (see docs/DECISIONS.md D-003). */
  KDF_ITERATIONS?: string;
  /** Test-only overrides (never set on a real installation; whoever can set them already controls the Worker). */
  RELEASE_API_BASE?: string;
  RELEASE_DL_BASE?: string;
  CF_API_BASE?: string;
  RELEASE_PUBLIC_KEY?: string;
  RELEASE_CHECK_GAP_MS?: string;
}

export const APP_VERSION = "0.14.0";
